corrected_code:
const securityResolvers = {
  Subscription: {
    securityAlarmTriggered: {
      subscribe: withFilter(
        () => pubsub.asyncIterator(['ALARM_BROADCAST']),
        async (payload, args, context) => {
          if (!context.user || payload.propertyId !== args.propertyId) return false;
          const property = await Property.findOne({ where: { id: args.propertyId, ownerId: context.user.id } });
          return !!property;
        }
      ),
      resolve: (payload) => payload.alarmEvent
    }
  }
};
